return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=3; plural=(((((((0 == 0)) && ((((n == 0)) == 0))) && (((n % 1000000) == 0))) && ((0 == 0))) || ((((0 >= 0 && 0 <= 5)) == 0))) ? 1 : (((n == 1)) && ((0 == 0))) ? 0 : 2);','language'=>'it_IT','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T07:20:41+00:00','po-revision-date'=>'2026-09-26T07:20:41+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'La versione iniziale del Page Builder Sandwich ricostruito: una schermata delle impostazioni e Informazioni, un livello di output front-end senza tracce SEO e un blocco di contenuto di esempio.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Provider di IA','The makers of ChatGPT. A good all-rounder.'=>'I creatori di ChatGPT. Un buon tuttofare.','The makers of Claude. Strong at writing and careful reasoning.'=>'I creatori di Claude. Eccellenti nella scrittura e nel ragionamento accurato.','Google\'s Gemini models. Fast and inexpensive.'=>'I modelli Gemini di Google. Veloci ed economici.','A European AI company with fast, inexpensive models.'=>'Un\'azienda europea di intelligenza artificiale con modelli veloci ed economici.','Low-cost models that are good at writing and code.'=>'Modelli economici che eccellono nella scrittura e nel codice.','One key for models from many different providers.'=>'Una sola chiave per modelli di molti provider diversi.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Qualsiasi servizio che funzioni come l\'API di OpenAI, compreso un modello in esecuzione sul proprio computer o server.','General (used when nothing more specific is set)'=>'Generale (utilizzato quando non è impostato nulla di più specifico)','Writing and rewriting'=>'Scrittura e riscrittura','Translation'=>'Traduzione','Code and CSS'=>'Codice e CSS','Sorry, you are not allowed to access this page.'=>'Siamo spiacenti, non disponi dell\'autorizzazione per accedere a questa pagina.','These settings are shared by every plugin that uses them: %s.'=>'Queste impostazioni sono condivise da tutti i plugin che le utilizzano: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Le Sue chiavi sono crittografate nel database di questo sito e vengono inviate esclusivamente al provider da Lei scelto, mai a noi.','Step 1 of 2: choose an AI provider'=>'Passaggio 1 di 2: scegli un provider di IA','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Porti la Sua chiave, quindi paga direttamente il fornitore per ciò che utilizza. Ha dei dubbi? Ognuna di queste opzioni funziona bene; potrà aggiungerne altre in seguito.','Next'=>'Avanti','Step 2 of 2: connect %s'=>'Passaggio 2 di 2: collega %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Inserire l\'indirizzo del Suo servizio compatibile con OpenAI, terminando con /v1. Una chiave è necessaria solo se il servizio ne richiede una.','Open %s and sign in (or create a free account).'=>'Apri %s e accedi (o crea un account gratuito).','the %s API keys page'=>'la pagina delle chiavi API %s','Create a new key and copy it.'=>'Crea una nuova chiave e copiala.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Incollalo qui sotto e premi "Salva e prova". Invieremo una piccolissima richiesta per verificare che funzioni.','Most providers need a little credit on the account before a key works: %s.'=>'La maggior parte dei provider richiede un piccolo credito sul conto prima che una chiave funzioni: %s.','add credit'=>'aggiungi credito','← Choose a different provider'=>'← Scegli un provider diverso','Address'=>'Indirizzo','Saved key ends in …%s — paste a new one to replace it'=>'La chiave salvata termina con …%s — incollane una nuova per sostituirla','Key (optional)'=>'Chiave (facoltativa)','API key'=>'Chiave API','Save and test'=>'Salva e prova','Providers'=>'Fornitori','Provider'=>'Provider','Status'=>'Stato','Key'=>'Chiave','Get a key'=>'Ottieni una chiave','Test'=>'Test','Remove'=>'Rimuovi','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Salvato da una versione più recente del plugin: aggiorna questo plugin o inserisci nuovamente la chiave.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'La chiave salvata non può più essere aperta (le chiavi di sicurezza del sito sono cambiate). Inseriscila di nuovo.','Not connected'=>'Non connesso','Connected — last test passed %s'=>'Connesso — ultimo test superato %s','Last test failed: %s'=>'Ultimo test non riuscito: %s','Connected — not tested yet'=>'Connesso — non ancora testato','Which model to use'=>'Quale modello utilizzare','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ contrassegna la nostra raccomandazione per quell\'attività. L\'elenco include ogni modello che la Sua chiave può utilizzare, letto in tempo reale dal provider.','— Recommended for the provider —'=>'— Consigliato per il provider —','Save models'=>'Salva modelli','Refresh the model lists from the providers'=>'Aggiorna gli elenchi dei modelli dai provider','best quality'=>'migliore qualità','lowest cost'=>'costo inferiore','fastest'=>'più veloce','Add a model yourself'=>'Aggiungi un modello tu stesso','A model came out today? Paste its exact name to use it straight away.'=>'È uscito un nuovo modello oggi? Incolla il suo nome esatto per utilizzarlo subito.','Model name'=>'Nome del modello','Add model'=>'Aggiungi modello','Recommended models list'=>'Elenco dei modelli consigliati','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Non è stato possibile verificare l\'elenco dei modelli consigliati, quindi non viene mostrato alcun consiglio. Reinstallare il plug-in o attivare gli aggiornamenti giornalieri di seguito.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'L\'elenco in uso è stato pubblicato il %s. Ogni aggiornamento del plugin ne fornisce uno nuovo.','Also check Zinn Digital® once a day for an updated list.'=>'Controlla anche Zinn Digital® una volta al giorno per un elenco aggiornato.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Viene inviata solo una semplice richiesta di download: nessuna chiave, nessun indirizzo del sito, nulla riguardo ai Suoi contenuti. L\'elenco è firmato e un elenco che non supera il controllo della firma viene ignorato.','Last checked %1$s: %2$s.'=>'Ultimo controllo %1$s: %2$s.','Save, and check now if turned on'=>'Salva e verifica ora se è attivato','a newer list was installed'=>'è stata installata un\'altra lista più recente','already up to date'=>'già aggiornato','the download failed the signature check and was ignored'=>'il download non ha superato il controllo della firma ed è stato ignorato','Zinn Digital® could not be reached; the current list stays in use'=>'Non è stato possibile raggiungere Zinn Digital®; l\'elenco corrente rimane in uso','turned off'=>'disattivato','Open'=>'Apri','Check their status page'=>'Controlla la loro pagina di stato','Open your billing page'=>'Apri la pagina di fatturazione','Open your API keys page'=>'Apra la pagina delle chiavi API','Open the AI settings'=>'Apri le impostazioni IA','Sorry, you are not allowed to do that.'=>'Spiacenti, non disponi dell\'autorizzazione per farlo.','Unknown provider.'=>'Provider sconosciuto.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Inserisca l\'indirizzo del Suo servizio, ad esempio http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Non sembra una chiave API. Copiala di nuovo, senza spazi.','Paste your API key first.'=>'Incolli prima la Sua chiave API.','Key removed.'=>'Chiave rimossa.','Models saved.'=>'Modelli salvati.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Inserisci il nome esatto del modello, ad esempio come è scritto nella documentazione del provider.','Added %s. Choose it under "Which model to use".'=>'Aggiunto %s. Sceglilo sotto "Quale modello utilizzare".','Model removed.'=>'Modello rimosso.','Daily updates are off. The list that came with the plugin is used.'=>'Gli aggiornamenti giornalieri sono disattivati. Viene utilizzata l\'elenco fornito con il plugin.','Checked: %s.'=>'Selezionato: %s.','Model lists refreshed.'=>'Elenchi di modelli aggiornati.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'La Sua chiave IA è stata salvata da una versione più recente di uno dei Suoi plugin. Aggiorni questo plugin o inserisca nuovamente la chiave nelle impostazioni dell\'IA.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'La chiave IA salvata non può più essere aperta (le chiavi di sicurezza del sito sono cambiate). Inseriscila di nuovo nelle impostazioni IA.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'L\'IA non è ancora configurata. Aggiungi una chiave per un provider di IA nelle impostazioni dell\'IA.','No model is chosen for this task. Pick one in the AI settings.'=>'Nessun modello è selezionato per questa attività. Scegline uno nelle impostazioni dell\'intelligenza artificiale.','That AI provider is not supported by this version of the plugin.'=>'Quel fornitore di intelligenza artificiale non è supportato da questa versione del plugin.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Questo sito non è riuscito a raggiungere il vostro servizio di IA. Verificate che sia in esecuzione e che il suo indirizzo sia raggiungibile dal vostro server web (un servizio sul vostro computer non è raggiungibile da un sito ospitato).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Questo sito non è riuscito a raggiungere %s. Verificare la pagina di stato; se il servizio è attivo, l\'host potrebbe bloccare le connessioni in uscita o l\'indirizzo potrebbe essere errato.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s comunica che il Suo account non ha più credito o quota disponibile. Aggiunga credito o aumenti il limite nel Suo account presso di loro, quindi riprovi.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s non ha accettato la Sua chiave. Potrebbe essere stata digitata male, revocata o scaduta. Crei una nuova chiave e la incolli qui.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s ha rifiutato questa richiesta per la Sua chiave. La chiave potrebbe non avere accesso a questo modello o a questa funzione, oppure il Suo account deve essere verificato.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Il modello "%1$s" non è disponibile da %2$s per la Sua chiave. Scelga un altro modello nelle impostazioni dell\'IA.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s sta limitando la velocità con cui la Sua chiave può inviare richieste. Attenda un minuto e riprovi, oppure aumenti il limite di frequenza con loro.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s sta riscontrando problemi in questo momento (un\'interruzione o un sovraccarico da parte loro). Le Sue impostazioni non presentano problemi. Riprovi a breve.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'La richiesta IA non è riuscita per un motivo che non siamo riusciti a identificare. Riprova; se il problema persiste, contatta il supporto con i dettagli di seguito.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Il provider di IA ha risposto in un formato che questo plugin non è riuscito a leggere. Riprova; se il problema persiste, scegli un altro modello o contatta il supporto.','Custom (OpenAI-compatible)'=>'Personalizzato (compatibile con OpenAI)','Save a key for this provider first.'=>'Salvare prima una chiave per questo provider.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'La Sua chiave funziona, ma il provider non elenca alcun modello di testo per essa. Aggiungine uno tu stesso qui sotto.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Connesso. %1$s ha risposto utilizzando %2$s. Le Sue funzionalità di intelligenza artificiale sono pronte per l\'uso.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Al Suo ruolo utente non è consentito utilizzare l\'IA su questo sito. Si rivolga a un amministratore.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Questo sito ha raggiunto il limite di spesa mensile per l\'IA. Un amministratore può aumentarlo nelle impostazioni dell\'IA.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Questo sito ha raggiunto il limite mensile di richieste AI. Un amministratore può aumentarlo nelle impostazioni AI.','Usage and cost'=>'Utilizzo e costi','The log, limits and role permissions apply to AI used through: %s.'=>'Il registro, i limiti e i permessi di ruolo si applicano all\'IA utilizzata tramite: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'I costi sono approssimativi, calcolati dai prezzi pubblicati; un modello senza prezzo noto viene conteggiato come zero.','This month: %1$s requests, about %2$s.'=>'Questo mese: %1$s richieste, circa %2$s.','When'=>'Quando','Who'=>'Chi','Used for'=>'Utilizzato per','Model'=>'Modello','Tokens in / out'=>'Token in / out','About'=>'Informazioni','Result'=>'Risultato','No AI requests have been made yet.'=>'Non è stata ancora effettuata alcuna richiesta di IA.','Done'=>'Completato','Limits and permissions'=>'Limiti e autorizzazioni','Monthly spending limit (US dollars)'=>'Limite di spesa mensile (dollari US)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Lasciare vuoto per nessun limite. L\'intelligenza artificiale si ferma per il resto del mese una volta raggiunto il costo approssimativo.','Monthly request limit'=>'Limite di richieste mensili','Leave empty for no limit.'=>'Lasciare vuoto per nessun limite.','Who may use AI'=>'Chi può utilizzare l\'IA','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Non selezionare nulla per consentire a chiunque possa utilizzare le funzionalità del plugin di usare l\'IA. Gli amministratori possono utilizzarla sempre.','Save limits and permissions'=>'Salva limiti e permessi','Limits and permissions saved.'=>'Limiti e permessi salvati.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Gli script della schermata di amministrazione mancano in questa copia del plugin. Reinstallalo da un pacchetto rilasciato.','This screen needs JavaScript.'=>'Questa schermata richiede JavaScript.','Languages'=>'Lingue','Upgrade'=>'Aggiorna','Pricing'=>'Prezzi','Start Trial'=>'Inizia la prova gratuita','Account'=>'Account','Contact Us'=>'Contattaci','Affiliation'=>'Affiliazione','the kind of softwarePlugin'=>'Plugin','greetingHey %s,'=>'Ciao %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Accetti di ricevere notifiche via email per aggiornamenti su sicurezza e funzionalità, contenuti educativi e offerte occasionali, e di condividere alcune informazioni di base sull\'ambiente WordPress. Ciò ci aiuterà a rendere il %s più compatibile con il Suo sito e più efficiente nel soddisfare le Sue esigenze.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Iscriviti per ricevere notifiche via email su aggiornamenti di sicurezza e funzionalità, contenuti formativi e offerte occasionali, e per condividere alcune informazioni di base sull\'ambiente WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Se salti questo passaggio, nessun problema! %1$s continuerà a funzionare perfettamente.','Allow & Continue'=>'Consenti e continua','verbSkip'=>'Salta','Skipping, please wait'=>'Salto in corso, attendere prego','Continue'=>'Continua','Please wait'=>'Attendere prego','as activating pluginActivating'=>'Attivazione in corso','This will allow %s to'=>'Questo consentirà a %s di','Privacy Policy'=>'Informativa sulla privacy','Terms of Service'=>'Termini di servizio','License Agreement'=>'Contratto di licenza','Have a license key?'=>'Hai una chiave di licenza?','Activate License'=>'Attiva licenza','View Basic Profile Info'=>'Visualizza le informazioni di base del profilo','Your WordPress user\'s: first & last name, and email address'=>'I dati utente del Suo WordPress: nome, cognome e indirizzo email','View Basic Website Info'=>'Visualizza le informazioni di base del sito web','Homepage URL & title, WP & PHP versions, and site language'=>'URL e titolo della homepage, versioni di WP e PHP e lingua del sito','View Basic %s Info'=>'Visualizza informazioni di base su %s','Current %s & SDK versions, and if active or uninstalled'=>'Versioni correnti di %s e SDK e stato di attività o disinstallazione','Newsletter'=>'Newsletter','Updates, announcements, marketing, no spam'=>'Aggiornamenti, annunci, marketing, niente spam','View Diagnostic Info'=>'Visualizza informazioni di diagnostica','WordPress & PHP versions, site language & title'=>'Versioni WordPress e PHP, lingua e titolo del sito','View Plugins & Themes List'=>'Visualizza elenco di plugin e temi','Names, slugs, versions, and if active or not'=>'Nomi, slug, versioni e stato di attivazione','optional'=>'opzionale','Never miss an important update'=>'Non perdere mai un aggiornamento importante','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Abbiamo introdotto questa opzione di consenso per fare in modo che non perdiate mai un aggiornamento importante e per aiutarci a rendere %s più compatibile con il vostro sito e più efficace nel soddisfare le vostre esigenze.','Thank you for updating to %1$s v%2$s!'=>'Grazie per aver eseguito l\'aggiornamento a %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Il prefisso deve essere composto da 1 a 8 lettere minuscole o cifre, iniziare con una lettera e non deve coincidere con il nome del plugin.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Creato da Neil Lock, CEO di Zinn Digital® Ltd','Version %s'=>'Versione %s','Page Builder Sandwich website'=>'Sito web di Page Builder Sandwich','Zinn Digital® website'=>'Sito web di Zinn Digital®','Settings saved.'=>'Impostazioni salvate.','See the Pro plans and pricing'=>'Visualizza i piani Pro e i prezzi','Front-end output'=>'Output front-end','Class name prefix'=>'Prefisso nome classe','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Ogni nome di classe stampato dal plugin sulle vostre pagine inizia con questo prefisso, in modo che le pagine non rivelino quale plugin le ha generate. Da 1 a 8 lettere minuscole o cifre, che iniziano con una lettera.','Save'=>'Salva','Beta updates'=>'Aggiornamenti beta','This site receives beta versions as updates.'=>'Questo sito riceve versioni beta come aggiornamenti.','This site receives stable versions only.'=>'Questo sito riceve solo versioni stabili.','Change this on the Account page'=>'Modifica questa impostazione nella pagina dell\'account','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Le versioni beta sono offerte alle installazioni Pro con licenza collegate al proprio account. Una volta effettuato il collegamento, puoi partecipare dalla pagina Account.','Content'=>'Contenuto','Heading'=>'Intestazione','Text'=>'Testo','Style'=>'Stile','Plain'=>'Semplice','Accent'=>'Accento','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'Nessuna lingua disponibile per il passaggio. Il selettore viene visualizzato quando un plugin di traduzione elenca due o più lingue.','Switcher'=>'Selettore','Accessible label'=>'Etichetta accessibile','Show the current language'=>'Mostra la lingua corrente','block titleLanguage switcher (sample)'=>'Selettore lingua (campione)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'Elenca le lingue del sito dal plugin di traduzione, quando uno è attivo. Altrimenti non restituisce nulla.','block keywordlanguage'=>'Lingua','block keywordswitcher'=>'Selettore','block titleSample content'=>'Contenuto di esempio','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'Un\'intestazione e un paragrafo, visualizzati con nomi di classi neutri. È il blocco di riferimento per il contratto di traduzione.','block keywordsample'=>'campione','block keywordtext'=>'testo']];